#!/usr/bin/env python3
"""Regenerate fixtures: family prefix (setup + header, up to the first #section
call) from templates/families/<f>/resume.typ + a neutral spacing-measurement body."""
import pathlib, re
root = pathlib.Path(__file__).resolve().parents[2]
BODY = '''
// ---------- spacing-measurement body (neutral fake content) ----------
#section("Experience")[
#job("Role Title One", "Employer One", "Mar 2024 – present", "City · descriptor one")
- First bullet of the first entry, long enough to wrap onto a second line so that leading is visible between the wrapped lines of one bullet.
- Second bullet of the first entry.
- Third bullet of the first entry.

#job("Role Title Two", "Employer Two", "Jul 2021 – Feb 2024", "City · descriptor two")
- First bullet of the second entry.
- Second bullet of the second entry, also long enough to wrap onto a second line for the leading measurement.

#job("Role Title Three", "Employer Three", "Sep 2019 – Jun 2021", "City · descriptor three")
- First bullet of the third entry.
- Second bullet of the third entry.
- Third bullet of the third entry.

#job("Role Title Four", "Employer Four", "Jan 2018 – Aug 2019", "City · descriptor four")
- First bullet of the fourth entry.
- Second bullet of the fourth entry.
]

#section("Education")[
#job("Degree Name One", "Institution One", "2015 – 2019", "City · note")
- First sub-line of the degree.
- Second sub-line of the degree.

#job("Degree Name Two", "Institution Two", "2013 – 2015", "City · note")
- First sub-line of the second degree.
- Second sub-line of the second degree.

#job("Certificate Three", "Institution Three", "2011 – 2012", "City · note")
- Single sub-line.
- Another sub-line.
]

#section("Skills")[
#skill("Programming", "Alpha, Beta, Gamma, Delta, Epsilon")
#skill("Backend", "Zeta, Eta, Theta, Iota, Kappa, Lambda, Mu, Nu, Xi, Omicron, Pi, Rho, Sigma, Tau, Upsilon, Phi, Chi, Psi, Omega")
#skill("Tools", "One, Two, Three, Four")
]
'''
for d in sorted((root/"templates/families").iterdir()):
    if not d.is_dir(): continue
    src = (d/"resume.typ").read_text().splitlines()
    i = next(n for n,l in enumerate(src) if l.startswith("#section("))
    pre = "\n".join(src[:i])
    pre = pre.replace('#import "../../lib.typ"', '#import "../../templates/lib.typ"')
    (root/"tests/fixtures"/f"{d.name}.typ").write_text(
        f"// FIXTURE ({d.name}): generated by gen.py from templates/families/{d.name}/resume.typ\n"+pre+"\n"+BODY)
